function Titulo($texto) {
    Write-Host ""
    Write-Host ("=" * 68) -ForegroundColor DarkCyan
    Write-Host "  $texto" -ForegroundColor Cyan
    Write-Host ("=" * 68) -ForegroundColor DarkCyan
}

function Passo($texto)  { Write-Host ""; Write-Host "-> $texto" -ForegroundColor White }
function Bom($texto)    { Write-Host "   OK   $texto" -ForegroundColor Green }
function Nada($texto)   { Write-Host "   --   $texto" -ForegroundColor DarkGray }
function Alerta($texto) { Write-Host "   !!   $texto" -ForegroundColor Yellow }
function Morrer($texto) {
    Write-Host ""
    Write-Host "ERRO: $texto" -ForegroundColor Red
    Write-Host ""
    exit 1
}

# Hash do conteudo com as quebras de linha normalizadas. Sem isso, um
# arquivo identico salvo com CRLF pelo Windows pareceria diferente do
# original e o script recusaria trocar sem motivo.
function HashDoArquivo($caminho) {
    $bytes = [IO.File]::ReadAllBytes($caminho)
    $texto = [Text.Encoding]::UTF8.GetString($bytes)
    $texto = $texto.TrimStart([char]0xFEFF)
    $texto = $texto.Replace("`r`n", "`n")
    $sha = [Security.Cryptography.SHA256]::Create()
    try {
        $h = $sha.ComputeHash([Text.Encoding]::UTF8.GetBytes($texto))
    } finally {
        $sha.Dispose()
    }
    return ([BitConverter]::ToString($h) -replace "-", "").ToLower()
}

# Escreve preservando o estilo de quebra de linha que o arquivo ja tinha,
# para o git nao acusar o arquivo inteiro como alterado.
function EscreverArquivo($destino, $conteudoLF, $usarCRLF) {
    $texto = $conteudoLF
    if ($usarCRLF) { $texto = $texto.Replace("`n", "`r`n") }
    $pasta = Split-Path $destino -Parent
    if ($pasta -and -not (Test-Path $pasta)) {
        New-Item -ItemType Directory -Path $pasta -Force | Out-Null
    }
    $semBom = New-Object Text.UTF8Encoding($false)
    [IO.File]::WriteAllText($destino, $texto, $semBom)
}

function LerComoLF($caminho) {
    $bytes = [IO.File]::ReadAllBytes($caminho)
    $texto = [Text.Encoding]::UTF8.GetString($bytes)
    return $texto.TrimStart([char]0xFEFF).Replace("`r`n", "`n")
}

Titulo "Lazer & Sport - substituindo os arquivos"

if ($Simular) {
    Alerta "MODO SIMULACAO: nada vai ser escrito no disco."
}

# ---------------------------------------------------------- repositorio
Passo "Procurando a pasta do projeto"

function Achar-Repo($inicio) {
    if ([string]::IsNullOrWhiteSpace($inicio)) { return $null }
    $atual = $inicio
    while ($atual) {
        if ((Test-Path (Join-Path $atual "manage.py")) -and
            (Test-Path (Join-Path $atual "lazer"))) {
            return $atual
        }
        $pai = Split-Path $atual -Parent
        if ($pai -eq $atual) { return $null }
        $atual = $pai
    }
    return $null
}

$raiz = $null
foreach ($ponto in @($Repo, (Get-Location).Path, $PSScriptRoot)) {
    $raiz = Achar-Repo $ponto
    if ($raiz) { break }
}

if (-not $raiz) {
    Morrer "Nao achei o Lazer-Sport. Rode este script de dentro da pasta do projeto (a que tem o manage.py), ou passe -Repo 'C:\caminho\do\Lazer-Sport'."
}

Set-Location $raiz
Bom "projeto em $raiz"

# ------------------------------------------------------ abre o pacote
Passo "Abrindo o pacote de arquivos"
$temp = Join-Path $env:TEMP ("lazersport-" + [guid]::NewGuid().ToString("N"))
New-Item -ItemType Directory -Path $temp -Force | Out-Null
$zip = Join-Path $temp "arquivos.zip"
[IO.File]::WriteAllBytes($zip, [Convert]::FromBase64String(($B64 -replace "\s", "")))
Expand-Archive -Path $zip -DestinationPath $temp -Force
Remove-Item $zip -Force
Bom ("" + $ARQUIVOS.Count + " arquivos prontos")

# --------------------------------------------------------- backup
$carimbo = Get-Date -Format "yyyy-MM-dd_HH-mm-ss"
$backup = Join-Path $raiz ("_backup_" + $carimbo)

# ------------------------------------------------------ substituicao
Passo "Conferindo e trocando"

$novos = @()
$trocados = @()
$jaIguais = @()
$conflitos = @()

foreach ($item in $ARQUIVOS) {
    $destino = Join-Path $raiz $item.p
    $origem = Join-Path $temp $item.p

    if (-not (Test-Path $origem)) {
        Alerta ($item.p + " - faltando no pacote (pulado)")
        continue
    }

    $conteudo = LerComoLF $origem
    $existe = Test-Path $destino

    # ---- arquivo que ainda nao existe no projeto ----
    if (-not $existe) {
        if (-not $Simular) { EscreverArquivo $destino $conteudo $false }
        $novos += $item.p
        Bom ($item.p + "  (novo)")
        continue
    }

    $atual = HashDoArquivo $destino

    # ---- ja esta na versao nova ----
    if ($atual -eq $item.novo) {
        $jaIguais += $item.p
        Nada ($item.p + "  (ja estava atualizado)")
        continue
    }

    # ---- voce editou este arquivo: nao sobrescreve ----
    if ($item.tipo -eq "M" -and $atual -ne $item.base) {
        $conflitos += $item.p
        if (-not $Simular) {
            $guarda = Join-Path $backup $item.p
            $pastaGuarda = Split-Path $guarda -Parent
            if (-not (Test-Path $pastaGuarda)) {
                New-Item -ItemType Directory -Path $pastaGuarda -Force | Out-Null
            }
            Copy-Item $destino $guarda -Force
            EscreverArquivo ($destino + ".NOVO") $conteudo $false
        }
        Alerta ($item.p + "  - VOCE EDITOU ESTE. Nao toquei; deixei o .NOVO ao lado.")
        continue
    }

    if ($item.tipo -eq "A" -and $atual -ne $item.novo) {
        $conflitos += $item.p
        if (-not $Simular) { EscreverArquivo ($destino + ".NOVO") $conteudo $false }
        Alerta ($item.p + "  - ja existe e esta diferente. Deixei o .NOVO ao lado.")
        continue
    }

    # ---- igual ao original: troca segura ----
    if (-not $Simular) {
        $guarda = Join-Path $backup $item.p
        $pastaGuarda = Split-Path $guarda -Parent
        if (-not (Test-Path $pastaGuarda)) {
            New-Item -ItemType Directory -Path $pastaGuarda -Force | Out-Null
        }
        Copy-Item $destino $guarda -Force

        $tinhaCRLF = ([IO.File]::ReadAllText($destino)).Contains("`r`n")
        EscreverArquivo $destino $conteudo $tinhaCRLF
    }
    $trocados += $item.p
    Bom ($item.p + "  (substituido)")
}

Remove-Item $temp -Recurse -Force -ErrorAction SilentlyContinue

# ------------------------------------------------------------ resumo
Titulo "Resumo"

Write-Host ""
Write-Host ("  " + $trocados.Count + " substituidos") -ForegroundColor Green
Write-Host ("  " + $novos.Count + " criados") -ForegroundColor Green
Write-Host ("  " + $jaIguais.Count + " ja estavam atualizados") -ForegroundColor DarkGray
if ($conflitos.Count -gt 0) {
    Write-Host ("  " + $conflitos.Count + " precisam da sua atencao") -ForegroundColor Yellow
}

if ((Test-Path $backup) -and -not $Simular) {
    Write-Host ""
    Write-Host "  Backup do que havia antes:" -ForegroundColor White
    Write-Host ("    " + $backup) -ForegroundColor Yellow
    Write-Host "    (pode apagar essa pasta quando estiver tudo certo)" -ForegroundColor DarkGray
}

if ($conflitos.Count -gt 0) {
    Write-Host ""
    Write-Host "  ATENCAO - estes arquivos voce tinha editado:" -ForegroundColor Yellow
    foreach ($c in $conflitos) {
        Write-Host ("    " + $c) -ForegroundColor Yellow
    }
    Write-Host ""
    Write-Host "  Nao sobrescrevi nenhum deles. A versao nova esta ao lado," -ForegroundColor White
    Write-Host "  com .NOVO no final do nome. Compare os dois e junte o que" -ForegroundColor White
    Write-Host "  quiser manter. No PyCharm: botao direito no arquivo ->" -ForegroundColor White
    Write-Host "  Compare With... -> escolha o .NOVO" -ForegroundColor White
}

# ----------------------------------------------------------- migrate
if ($Simular) {
    Write-Host ""
    Alerta "Simulacao: nada foi escrito. Rode sem -Simular para valer."
} elseif ($SemMigrate) {
    Write-Host ""
    Alerta "migrate pulado (-SemMigrate). Rode depois: python manage.py migrate"
} elseif ($conflitos.Count -gt 0) {
    Write-Host ""
    Alerta "Nao rodei a migration porque ha arquivos pendentes acima."
    Alerta "Resolva os .NOVO e depois rode: python manage.py migrate"
} else {
    $python = $null
    foreach ($tentativa in @(
        (Join-Path $raiz ".venv\Scripts\python.exe"),
        (Join-Path $raiz "venv\Scripts\python.exe")
    )) {
        if (Test-Path $tentativa) { $python = $tentativa; break }
    }
    if (-not $python) {
        $doPath = Get-Command python -ErrorAction SilentlyContinue
        if ($doPath) { $python = $doPath.Source }
    }

    if (-not $python) {
        Write-Host ""
        Alerta "Nao achei o Python. Rode voce mesmo: python manage.py migrate"
    } else {
        Passo "Criando as tabelas do estoque (sistema_interno 0008)"
        $anterior = $ErrorActionPreference
        $ErrorActionPreference = "Continue"
        $saida = & $python "manage.py" "migrate" 2>&1
        $codigo = $LASTEXITCODE
        $ErrorActionPreference = $anterior

        if ($codigo -eq 0) {
            Bom "banco atualizado"
        } else {
            $saida | ForEach-Object { Write-Host "   $_" -ForegroundColor DarkGray }
            Write-Host ""
            Alerta "a migration nao rodou."
            Alerta "Se a mensagem fala em SUPABASE_DATABASE_URL, e o .env que esta"
            Alerta "faltando a variavel. Os arquivos ja foram trocados; depois de"
            Alerta "arrumar o .env rode: python manage.py migrate"
        }

        Passo "Publicando os arquivos estaticos"
        $ErrorActionPreference = "Continue"
        $saida = & $python "manage.py" "collectstatic" "--noinput" 2>&1
        $codigo = $LASTEXITCODE
        $ErrorActionPreference = $anterior
        if ($codigo -eq 0) { Bom "estaticos publicados" } else { Alerta "collectstatic falhou; rode depois se for usar WhiteNoise" }
    }
}

# ----------------------------------------------------------- final
Titulo "Pronto"

Write-Host ""
Write-Host "  Para ver funcionando:" -ForegroundColor White
Write-Host "    python manage.py runserver" -ForegroundColor Yellow
Write-Host ""
Write-Host "    http://localhost:8000/adm/brinquedos/    modal de imagens"
Write-Host "    http://interno.localhost:8000/           painel interno"
Write-Host "    http://interno.localhost:8000/stock/     estoque de materiais"
Write-Host ""
Write-Host "  Nao gostou? Copie de volta o que esta na pasta _backup_." -ForegroundColor DarkGray
Write-Host ""
